    @TempDir Path directory;
    static Command command(String main,String process,String info,String operation,String profile){Map<String,Object> values=obj();for(var e:obj("mainId",main,"collectionName","rbuModulesAppeals.subservices","camundaBusinessInfoId",info,"rbuDomain","TRADE","rbuProfile",profile,"rbuOperation",operation,"rbuContractVersion","1").entrySet())values.put(e.getKey(),obj("value",e.getValue()));return new Command(obj("id",operation+"-task","processInstanceId",process,"activityId",operation,"variables",values));}
    static Context context(Fake api,String operation)throws Exception{return new Context(command("appeal","process","info",operation,api.profile),api);}
    static Context rollbackContext(Fake api,String operation)throws Exception{return new Context(command("rollback","rollback-process","rollback-info",operation,api.profile),api);}
    @Test void realXlsxValidationImportRepeatAndRollback()throws Exception{Fake api=new Fake();try(Journal journal=new Journal(directory)){Operations operations=new Operations(journal,()->{},true,"https://test.example");assertEquals(true,operations.execute(context(api,"PARSE_VALIDATE")).get("rbuCanApply"));api.confirm();assertEquals(false,operations.execute(context(api,"IMPORT_APPLY")).get("rbuApplyHasMoreBatches"));assertEquals(3,api.created);operations.execute(context(api,"IMPORT_APPLY"));assertEquals(3,api.created);operations.execute(context(api,"IMPORT_FINALIZE"));api.rollback();operations.execute(rollbackContext(api,"ROLLBACK_PREPARE"));api.confirmRollback();operations.execute(rollbackContext(api,"ROLLBACK_EXECUTE"));operations.execute(rollbackContext(api,"ROLLBACK_FINALIZE"));assertEquals(3,api.deleted);assertEquals("ROLLED_BACK",at(api.cases.get("rollback"),"rollbackResultStatus"));}}
