    @Test void rollbackRejectsChangedGuidBeforeOrAfterPreparationAndTamperedJournal()throws Exception{Fake api=new Fake();try(Journal journal=new Journal(directory)){Operations operations=new Operations(journal,()->{},true,"https://test.example");operations.execute(context(api,"PARSE_VALIDATE"));api.confirm();operations.execute(context(api,"IMPORT_APPLY"));Map<String,Object> place=api.first("NTOmesto");String original=clean(place.get("guid"));place.put("guid","changed-before");api.rollback();operations.execute(rollbackContext(api,"ROLLBACK_PREPARE"));assertTrue(integer(at(api.sub("rollback"),"rbuRollbackPlan.blockedRecords"))>=2);place.put("guid",original);api.rollback();operations.execute(rollbackContext(api,"ROLLBACK_PREPARE"));place.put("guid","changed-after");api.confirmRollback();operations.execute(rollbackContext(api,"ROLLBACK_EXECUTE"));assertTrue(api.records.get("NTOmesto").containsKey(id(place)));assertTrue(integer(at(api.sub("rollback"),"rbuRollbackPlan.blockedRecords"))>=2);place.put("guid",original);api.rollback();put(api.sub("appeal"),"tradeMigrationSummary.workerRunKey","a".repeat(64));assertThrows(IllegalArgumentException.class,()->operations.execute(rollbackContext(api,"ROLLBACK_PREPARE")));}}
