    @Test void activeReferenceInEachCaseCollectionProtectsPrimaryAndItsMirror()throws Exception{
        for(String collection:List.of("metaReglamentNtoAppeals","reglamentNtoAppeals","reglamentMarketAppeals","rbuModulesAppeals")){
            Fake api=new Fake();try(Journal journal=new Journal(directory.resolve(collection))){
                Operations operations=new Operations(journal,()->{},true,"https://test.example");operations.execute(context(api,"PARSE_VALIDATE"));api.confirm();operations.execute(context(api,"IMPORT_APPLY"));
                Map<String,Object> place=api.first("NTOmesto");Map<String,Object> active=obj("_id","active-case","number","ACTIVE-1","status",obj("code","process"),"subservices",List.of(obj("xsdData",obj("selectedRecordId",id(place)))));
                api.records.computeIfAbsent(collection,k->new LinkedHashMap<>()).put(id(active),active);api.rollback();operations.execute(rollbackContext(api,"ROLLBACK_PREPARE"));
                Map<String,Object> plan=map(api.sub("rollback").get("rbuRollbackPlan"));assertEquals(2,integer(plan.get("blockedRecords")),collection);assertEquals(1,integer(plan.get("deletableRecords")),collection);
                Map<String,Object> blocked=maps(plan.get("items")).stream().filter(i->"NTOmesto".equals(i.get("collection"))).findFirst().orElseThrow();assertEquals("ACTIVE-1",at(active,"number"));assertEquals(collection,at(blocked,"activeCases.0.collection"));assertEquals("active-case",at(blocked,"activeCases.0.appealId"));
                api.confirmRollback();operations.execute(rollbackContext(api,"ROLLBACK_EXECUTE"));operations.execute(rollbackContext(api,"ROLLBACK_FINALIZE"));
                assertEquals(1,api.deleted,collection);assertEquals("PARTIAL",at(api.cases.get("rollback"),"rollbackResultStatus"));assertFalse(api.find("NTOmesto",id(place)).isEmpty(),collection);assertEquals(1,api.records.get("nsiLocalObjectNTO").size(),collection);
            }
        }
    }
