            Operations operations=new Operations(journal,()->{},true,"https://test.example");operations.execute(context(api,"PARSE_VALIDATE"));api.confirm();operations.execute(context(api,"IMPORT_APPLY"));api.rollback();operations.execute(rollbackContext(api,"ROLLBACK_PREPARE"));api.confirmRollback();api.loseDeleteResponse=true;api.loseDeleteVerification=true;
