    static byte[] workbook()throws Exception{return workbook(1);}
    static byte[] workbook(int places)throws Exception{Map<String,Object> draft=copy(TradeValidationTest.fixture().toMap());if(places>1)for(Map<String,Object> sheet:maps(draft.get("sheets")))if("sheet2".equals(sheet.get("code"))){Map<String,Object> original=maps(sheet.get("rows")).getFirst();List<Object> rows=new ArrayList<>();for(int n=0;n<places;n++){Map<String,Object> row=copy(original);row.put("excelRow",6+n);for(Map<String,Object> column:maps(sheet.get("columns")))for(Map<String,Object> cell:maps(row.get("cells")))if(column.get("column").equals(cell.get("column"))){String label=clean(column.get("fieldName"));if(label.equals("Номер в схеме"))cell.put("value",clean(cell.get("value"))+"-"+n);if(label.startsWith("Фотография объекта"))cell.put("value","");}rows.add(row);}sheet.put("rows",rows);}try(XSSFWorkbook workbook=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){
        var title=workbook.createSheet("1. Титульный лист");title.createRow(5).createCell(0).setCellValue("Субъект РФ");title.getRow(5).createCell(1).setCellValue(clean(at(draft,"title.region")));title.createRow(16).createCell(0).setCellValue("Муниципальное образование");title.getRow(16).createCell(1).setCellValue(clean(at(draft,"title.municipality")));
        for(Map<String,Object> sheet:maps(draft.get("sheets"))){var target=workbook.createSheet(clean(at(draft,"sheetNames."+sheet.get("code"))));for(int i=0;i<5;i++)target.createRow(i);target.getRow(0).createCell(0).setCellValue("№");target.getRow(3).createCell(0).setCellValue("Название поля");for(Map<String,Object> c:maps(sheet.get("columns"))){int col=CellReference.convertColStringToIndex(clean(c.get("column")));String[] names={"attribute","block","subBlock","fieldName","requiredMarker"};for(int i=0;i<5;i++)target.getRow(i).createCell(col).setCellValue(clean(c.get(names[i])));}for(Map<String,Object> row:maps(sheet.get("rows"))){var targetRow=target.createRow(integer(row.get("excelRow"))-1);for(Map<String,Object> c:maps(row.get("cells")))targetRow.createCell(CellReference.convertColStringToIndex(clean(c.get("column")))).setCellValue(clean(c.get("value")));}}
        var refs=workbook.createSheet("4. Значения для копирования");var head=refs.createRow(2);int column=0;for(Map<String,Object> entry:maps(at(draft,"referenceLists.entries"))){head.createCell(column).setCellValue(clean(entry.get("name")));int n=3;for(Object value:list(entry.get("values"))){var row=refs.getRow(n);if(row==null)row=refs.createRow(n);row.createCell(column).setCellValue(clean(value));n++;}column++;}workbook.write(out);return out.toByteArray();}}
    static final class Fake implements PgsApi{
        final Map<String,Map<String,Object>> cases=new LinkedHashMap<>();final Map<String,Map<String,Map<String,Object>>> records=new LinkedHashMap<>();final byte[] bytes;String profile="ROIV",regionCode="61",cardGuid="organization-guid",unavailableAfterDelete="";boolean permission=true,loseCreateResponse,loseDeleteResponse,loseDeleteVerification,normalizeNumericStorage,corruptNumericStorage;int created,deleted;
        Fake()throws Exception{this(1);}
        Fake(int places)throws Exception{bytes=workbook(places);Map<String,Object> title=map(TradeValidationTest.fixture().metadata().get("title"));Object files=Json.parse(new String(TradeWorkerLifecycleTest.class.getResourceAsStream("/trade/nto-files.json").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));cases.put("appeal",obj("_id","appeal","guid","appeal-guid","number","TRADE-TEST","unitId","organization","unit",obj("id","organization"),"status",obj("code","process"),"region",obj("_id","passport"),"municipality",obj("_id","municipality"),"organization",obj("_id","card","organizationId","organization"),"dataType","НТО","importFile",obj("_id","file","originalName","trade.xlsx"),"documents",new ArrayList<>(List.of(obj("groupName","Файлы миграции","files",files))),"subservices",new ArrayList<>(List.of(obj("guid","sub","standardCode","46535","parentEntries","rbuModulesAppeals.subservices","camundaProcessInfo",obj("id","process","camundaBusinessInfoId","info"),"xsdData",obj())))));}
        Map<String,Object>sub(String id){return maps(cases.get(id).get("subservices")).getFirst();}Map<String,Object>first(String collection){return records.get(collection).values().iterator().next();}
        void confirm(){put(sub("appeal"),"xsdData.rbuImportConfirmation",obj("confirmApply",true,"confirmationFingerprint",at(cases.get("appeal"),"importDraft.confirmationFingerprint")));}
        void rollback(){put(cases.get("appeal"),"status.code","complete");cases.put("rollback",obj("_id","rollback","guid","rollback-guid","number","RB-TEST","unitId","organization","unit",obj("id","organization"),"migrationCase",obj("_id","appeal"),"subservices",List.of(obj("guid","rb-sub","parentEntries","rbuModulesAppeals.subservices","camundaProcessInfo",obj("id","rollback-process","camundaBusinessInfoId","rollback-info"),"xsdData",obj()))));}
        void confirmRollback(){Map<String,Object> plan=map(sub("rollback").get("rbuRollbackPlan"));cases.get("rollback").put("rbuRollbackDecision",obj("confirmed",true,"targetAppealId","appeal","journalFingerprint",plan.get("journalFingerprint")));}
        public Map<String,Object>find(String collection,String id)throws Exception{if(loseDeleteVerification&&unavailableAfterDelete.equals(collection+"/"+id)){loseDeleteVerification=false;throw new IOException("DELETE verification response lost");}if(collection.equals("rbuModulesAppeals"))return copy(cases.getOrDefault(id,obj()));Map<String,Object> original=TradeValidationTest.registry(permission).findById(collection,id).orElse(obj());if(!original.isEmpty()){Map<String,Object> value=copy(original);if(collection.equals("organizations")){value.put("_id",id);value.put("guid",id.equals("organization")?"organization-guid":"coordinator-guid");value.put("regions",obj("code","61"));}if(collection.equals("rbuRegionOrganizations"))value.putAll(obj("registryScope","TRADE","organizationGuid",cardGuid,"municipalityId","municipality-id"));if(collection.equals("rbuRegionPassports"))value.put("regionCode",regionCode);if(collection.equals("rbuRegionMunicipalities"))value.put("municipalityId","municipality-id");return value;}return copy(records.getOrDefault(collection,Map.of()).getOrDefault(id,obj()));}
        public List<Map<String,Object>>search(String collection,List<Object> filters,int page,int size){if(collection.startsWith("nsiUnified")){if(page>0)return List.of();return TradeModuleTest.dictionaryRegistry().search(collection,obj("search",obj("search",filters)),size);}List<Map<String,Object>> found=new ArrayList<>();for(var row:records.getOrDefault(collection,Map.of()).values())if(matches(row,filters))found.add(copy(row));int start=Math.min(page*size,found.size());return found.subList(start,Math.min(start+size,found.size()));}
        boolean matches(Map<String,Object> record,List<Object> filters){for(Object value:filters){Map<String,Object> f=map(value);if(f.containsKey("orSubConditions")){boolean any=false;for(Object sub:list(f.get("orSubConditions")))any|=matches(record,List.of(sub));if(!any)return false;continue;}if(!f.containsKey("field"))continue;List<Object> actual=values(record,clean(f.get("field")).split("\\."),0);String op=clean(f.get("operator"));boolean equal=actual.stream().anyMatch(v->clean(v).equals(clean(f.get("value"))));if(op.equals("neq")){if(equal)return false;}else if(op.equals("in")){if(actual.stream().noneMatch(v->list(f.get("value")).contains(v)))return false;}else if(!equal)return false;}return true;}
        static List<Object> values(Object value,String[]path,int index){List<Object> out=new ArrayList<>();if(value instanceof List){for(Object item:list(value))out.addAll(values(item,path,index));}else if(index==path.length)out.add(value);else if(value instanceof Map)out.addAll(values(map(value).get(path[index]),path,index+1));return out;}
        public void update(String collection,String id,String guid,Map<String,Object> patch){if(collection.equals("rbuModulesAppeals"))cases.get(id).putAll(copy(patch));else records.get(collection).get(id).putAll(copy(patch));}
        public void updateSub(String collection,String id,String guid,String parent,Map<String,Object> patch){for(Map<String,Object> s:maps(cases.get(id).get("subservices")))if(guid.equals(s.get("guid")))s.putAll(copy(patch));}
        public Map<String,Object>create(String collection,Map<String,Object> payload)throws Exception{Map<String,Object> row=copy(payload);if(normalizeNumericStorage||corruptNumericStorage)for(String field:List.of("PeriodicContractFee","TotalContractFee")){Object value=at(row,"NTOContract."+field);if(value instanceof Number)put(row,"NTOContract."+field,Double.valueOf(clean(value))+(corruptNumericStorage?0.01:0));}row.put("_id",String.format("%024x",++created));records.computeIfAbsent(collection,k->new LinkedHashMap<>()).put(id(row),row);if(loseCreateResponse){loseCreateResponse=false;throw new IOException("Committed CREATE response lost");}return copy(row);}
        public void delete(String collection,String id,String guid)throws Exception{Map<String,Object> row=records.getOrDefault(collection,Map.of()).get(id);if(row!=null){assertEquals(guid,row.get("guid"));records.get(collection).remove(id);deleted++;if(loseDeleteResponse){loseDeleteResponse=false;unavailableAfterDelete=collection+"/"+id;throw new IOException("Committed DELETE response lost");}}}
        public byte[]download(String id,long max){assertEquals("file",id);return bytes;}
    }
